//! Conformance tests for `wedeo-codec-hevc-dsp`.
//!
//! The vectors in `wedeo_codec_hevc_dsp::reference_vectors` were generated by
//! compiling FFmpeg's own C kernels (extracted verbatim from
//! `libavcodec/hevc/pred_template.c`, `libavcodec/h26x/h2656_*_template.c` and
//! `libavcodec/hevc/dsp_template.c`) and recording their outputs. This test
//! replays them through the public Rust API.

use wedeo_codec_hevc_dsp::deblock;
use wedeo_codec_hevc_dsp::inter;
use wedeo_codec_hevc_dsp::intra;
use wedeo_codec_hevc_dsp::reference_vectors as rv;
use wedeo_codec_hevc_dsp::sao;
use wedeo_codec_hevc_dsp::transform;

fn px(name: &str) -> Vec<u16> {
    rv::get(name).iter().map(|&v| v as u16).collect()
}

fn i16v(name: &str) -> Vec<i16> {
    rv::get(name).iter().map(|&v| v as i16).collect()
}

fn check_u16(name: &str, got: &[u16]) {
    let want = px(name);
    assert_eq!(got, want.as_slice(), "FFmpeg vector {name}");
}

fn check_i16(name: &str, got: &[i16]) {
    let want = i16v(name);
    assert_eq!(got, want.as_slice(), "FFmpeg vector {name}");
}

#[test]
fn fate_hevc_dsp_vector_inventory() {
    // 245 vectors generated from the C source; a truncated file is a failure.
    assert!(rv::get("INTRA_PLANAR_32").len() == 1024);
    assert!(rv::get("IDCT_32").len() == 1024);
    assert!(rv::get("DEBLOCK_INPUT").len() == 256);
    assert!(rv::get("SAO_SRC").len() == 1920);
    assert_eq!(deblock::TC_TABLE.len(), 54);
    assert_eq!(deblock::BETA_TABLE.len(), 52);
}

#[test]
fn fate_hevc_dsp_intra() {
    for log2 in 2..=5 {
        let size = 1usize << log2;
        let refs = intra::IntraRefSamples {
            corner: px(&format!("INTRA_CORNER_{size}"))[0],
            top: px(&format!("INTRA_REF_TOP_{size}")),
            left: px(&format!("INTRA_REF_LEFT_{size}")),
        };
        let mut dst = vec![0u16; size * size];
        for (mode, name) in [
            (intra::IntraPredMode::Planar, format!("INTRA_PLANAR_{size}")),
            (intra::IntraPredMode::DC, format!("INTRA_DC_LUMA_{size}")),
        ] {
            intra::intra_predict(&mut dst, size, log2, mode, 0, &refs, 8).unwrap();
            check_u16(&name, &dst);
        }
        let modes: &[u8] = match size {
            4 => &(2..=34).collect::<Vec<_>>(),
            8 | 16 => &[2, 10, 18, 26, 34],
            _ => &[2, 10, 18, 26, 34],
        };
        for &m in modes {
            intra::intra_predict(
                &mut dst,
                size,
                log2,
                intra::IntraPredMode::Angular(m),
                0,
                &refs,
                8,
            )
            .unwrap();
            check_u16(&format!("INTRA_ANG_{size}_{m}_L"), &dst);
        }
    }
}

#[test]
fn fate_hevc_dsp_inter() {
    let src = px("INTER_SRC");
    let src2 = i16v("INTER_SRC2");
    let mut tmp = vec![0i16; 8 * wedeo_codec_hevc_dsp::MAX_PB_SIZE];
    let mut dst = vec![0u16; 64];
    for (mx, my) in [(0, 0), (1, 0), (0, 2), (3, 3)] {
        let params = inter::McParams::new(8, mx, my).unwrap();
        inter::put_luma(
            &mut tmp,
            wedeo_codec_hevc_dsp::MAX_PB_SIZE,
            &src,
            16,
            8,
            8,
            4,
            4,
            params,
        )
        .unwrap();
        check_i16(&format!("INTER_PUT_LUMA_{mx}_{my}"), &tmp);
        inter::uni_luma(&mut dst, 8, &src, 16, 8, 8, 4, 4, params).unwrap();
        check_u16(&format!("INTER_UNI_LUMA_{mx}_{my}"), &dst);
        inter::bi_luma(
            &mut dst,
            8,
            &src,
            16,
            &src2,
            wedeo_codec_hevc_dsp::MAX_PB_SIZE,
            8,
            8,
            4,
            4,
            params,
        )
        .unwrap();
        check_u16(&format!("INTER_BI_LUMA_{mx}_{my}"), &dst);
    }
}

#[test]
fn fate_hevc_dsp_transforms_and_filters() {
    for log2 in 2..=5 {
        let size = 1usize << log2;
        let mut coeffs = i16v(&format!("COEFF_INPUT_{size}"));
        transform::dequant(&mut coeffs, log2, 8).unwrap();
        check_i16(&format!("DEQUANT_8_{size}"), &coeffs);

        let mut coeffs = i16v(&format!("COEFF_INPUT_{size}"));
        if size == 4 {
            transform::transform_4x4_luma(&mut coeffs, 8).unwrap();
        } else {
            transform::idct(&mut coeffs, log2, 0, 8).unwrap();
        }
        check_i16(&format!("IDCT_{size}"), &coeffs);
    }

    let input: Vec<u16> = px("DEBLOCK_INPUT");
    let mut block = input.clone();
    deblock::loop_filter_luma(
        &mut block,
        6 * 16 + 6,
        1,
        16,
        26,
        &[10, 12],
        &[false, false],
        &[false, true],
        8,
    )
    .unwrap();
    check_u16("DEBLOCK_LUMA", &block);

    let src: Vec<u16> = px("SAO_SRC");
    let stride =
        2 * wedeo_codec_hevc_dsp::MAX_PB_SIZE + wedeo_codec_hevc_dsp::AV_INPUT_BUFFER_PADDING_SIZE;
    let offsets = [0i16, -3, 5, -7, 9];
    let mut dst = vec![0u16; 64];
    sao::sao_band_filter(
        &mut dst,
        8,
        &src[stride + 1..],
        stride,
        &offsets,
        7,
        8,
        8,
        8,
    )
    .unwrap();
    check_u16("SAO_BAND", &dst);
    for eo in 0..=3 {
        let mut dst = vec![0u16; 64];
        sao::sao_edge_filter(&mut dst, 8, &src, stride, &offsets, eo, 8, 8, 8).unwrap();
        check_u16(&format!("SAO_EDGE_{eo}"), &dst);
    }
}
